```javascript
const input = require('fs').readFileSync('/dev/stdin', 'utf8')
  .trim()
  .split(/\s+/)
  .map(Number);

const N = input[0];
const M = input[1];
const S = input[2];

function digitSum(x) {
  let s = 0;
  while (x > 0) {
    s += x % 10;
    x = Math.floor(x / 10);
  }
  return s;
}

let ans = -1;
for (let i = M; i >= N; i--) {
  if (digitSum(i) === S) {
    ans = i;
    break;
  }
}

console.log(ans);
